package com.yuegang.zhihui.ai.infrastructure;import com.yuegang.zhihui.ai.domain.*;import com.yuegang.zhihui.common.core.ApiResponse;import com.yuegang.zhihui.search.api.*;import java.util.*;import org.springframework.web.client.RestClient;public final class HttpRetrievalGateway implements RetrievalGateway{private final RestClient client;public HttpRetrievalGateway(String base){client=RestClient.builder().baseUrl(base).build();}public List<SearchHit>search(String q,String c,int limit){@SuppressWarnings("unchecked")ApiResponse<List<Map<String,Object>>>r=client.post().uri("/internal/v1/search/hybrid").body(new SearchRequest(q,limit,c)).retrieve().body(ApiResponse.class);if(r==null||r.data()==null)return List.of();return r.data().stream().map(x->new SearchHit(Objects.toString(x.get("documentId")),Objects.toString(x.get("chunkId")),Objects.toString(x.get("title")),Objects.toString(x.get("excerpt")),number(x.get("lexicalScore")),number(x.get("vectorScore")),number(x.get("finalScore")))).toList();}private static double number(Object v){return v instanceof Number n?n.doubleValue():0;}}
